19354e7-fbf9-427b-aa91-55017b027e0a","orden":110,"contenido_md5":"07cf73678d39d1c94eb212b342fddfde"},{"identificador":"Transitorio Segundo · decreto","tipo_articulo":"transitorio","titulo_nombre":"Transitorios del decreto","capitulo_nombre":null,"seccion_nombre":null,"id":"495e8f06-9b38-4c7d-a1e1-c9a9de0bbcd3","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","orden":111,"contenido_md5":"260936806544b43686d83d27d1e79323"},{"identificador":"Firmas y promulgación","tipo_articulo":"complementario","titulo_nombre":"Documentos complementarios","capitulo_nombre":null,"seccion_nombre":null,"id":"9c43a394-d870-5c83-bbf1-433074686e02","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","orden":112,"contenido_md5":"b2dbdb42cfe8ff60a81b5715d0559429"}],"after":[{"id":"446d1069-0c3d-438c-afe1-eea33271dd6c","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Preámbulo","contenido":"LEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN Se cretaría General Secretaría de Servicios Parlamentarios Nueva Ley DOF 18 - 03 - 2025 1 de 23 LEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA TEXTO VIGENTE Nueva Ley publicada en el Diario Oficial de la Federación el 18 de marzo de 2025 Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos. - Presidencia de la República. CLAUDIA SHEINBA UM PARDO , Presidenta de los Estados Unidos Mexicanos, a sus habitantes sabed: Que el Honorable Congreso de la Unión, se ha servido dirigirme el siguiente DECRETO \" EL CONGRESO GENERAL DE LOS ESTADOS UNIDOS MEXICANOS, DECRETA: SE EXPIDEN LA LEY DE LA EMPRESA PÚBLICA DEL ESTADO, COMISIÓN FEDERAL DE ELECTRICIDAD; LA LEY DE LA EMPRESA PÚBLICA DEL ESTADO, PETRÓLEOS MEXICANOS; LA LEY DEL SECTOR ELÉCTRICO; LA LEY DEL SECTOR HIDROCARBUROS; LA LEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA; LA LEY DE BIOCOMBUSTIBLES; LA L EY DE GEOTERMIA Y, LA LEY DE LA COMISIÓN NACIONAL DE ENERGÍA; SE REFORMAN DIVERSAS DISPOSICIONES DE LA LEY DEL FONDO MEXICANO DEL PETRÓLEO PARA LA ESTABILIZACIÓN Y EL DESARROLLO Y, SE REFORMAN, ADICIONAN Y DEROGAN DIVERSAS DISPOSICIONES DE LA LEY ORGÁNICA DE LA ADMINISTRACIÓN PÚBLICA FEDERAL ARTÍCULO PRIMERO A ART ÍCULO CUARTO . - … … … . ARTÍCULO QUINTO. - Se expide la Ley de Planeaci ón y Transición Energética, para quedar como sigue: LEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA TÍTULO PRIMERO Disposiciones Generales Capítulo Único Del Objeto de la Ley y Definiciones","tipo_articulo":"preambulo","titulo_nombre":null,"capitulo_nombre":null,"seccion_nombre":null,"orden":0},{"id":"cdcbdca4-267c-4774-94be-f7da143e98e7","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 1. -","contenido":"La presente Ley es reglamentaria de los artículos 25, párra fo tercero; 27, párrafos sexto y séptimo; \n 28, párrafo cuarto, de la Constitución Política de los Estados Unidos Mexicanos, es de orden público e interés social \n y de observancia general en los Estados Unidos Mexicanos. \n Tiene por objeto establecer y regular la planeación vinculante en el Sector Energético y el fortalecimiento de la \n Transición Energética, así como el Aprovechamiento Sustentable de la Energía, el cumplimiento de las obligaciones \n en materia de Energías Limpias y la reducción de Emisiones Contami nantes, manteniendo la competitividad de los \n sectores productivos, con el fin de coadyuvar con la soberanía, justicia y autosuficiencia energética.","tipo_articulo":"ordinario","titulo_nombre":"Disposiciones Generales","capitulo_nombre":null,"seccion_nombre":null,"orden":1},{"id":"cc0ff4c9-59ad-4f8c-acb3-906e691b33ae","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 2. -","contenido":"La Secretaría de Energía está a cargo de la planeación vinculante en el Sector Energético, que \n incluye, como parte esencial, el desarrollo de las áreas estratégicas para preservar la soberanía, la seguridad, la \n autosuficiencia y la Justicia Energética de la Nación; así como la prestación de servicios públicos para garantizar la \n continuidad, accesibi lidad, seguridad y confiabilidad del Sistema Eléctrico Nacional, de acuerdo con los objetivos \n siguientes: \n I. Garantizar que la planeación vinculante permita la prevalencia de la Comisión Federal de \n Electricidad en las actividades del sector eléctrico, toda vez que esta es la garante de la \n continuidad, accesibilidad, seguridad y confiabilidad del servicio público de electricidad y del \n Sistema Eléctrico Nacional; \n II. Impulsar el desarrollo sustentable del Sector Energético y preservar la seguridad y autosufic iencia \n energética de la Nación; \n III. Impulsar los proyectos de infraestructura estratégicos necesarios para cumplir con la política \n energética nacional y su ejecución; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 2 de 23 \n IV. Establecer y regular las obligaciones de los participantes del Sector Energético par a la Transición \n Energética, el Aprovechamiento Sustentable de la Energía, las Energías Limpias y la Eficiencia \n Energética para el Sector Energético; \n V. Establecer y regular los instrumentos de planeación del Sector Energético y de información \n energética; \n V I. Establecer y regular las obligaciones y los instrumentos para incentivar la innovación, desarrollo \n tecnológico y formación de recursos humanos en el Sector Energético; \n VII. Promover las Energías Limpias, el Aprovechamiento Sustentable de la Energía incl uyendo la \n Eficiencia Energética en los sectores productivos y de uso final de la energía, y la reducción de \n emisiones de gases y compuestos de efecto invernadero, así como de contaminantes del Sector \n Energético. Para este fin, la Secretaría puede crear mec anismos de financiamiento en programas y \n proyectos de interés público; \n VIII. Promover la Justicia Energética con mecanismos eficientes y sustentables para reducir la Pobreza \n Energética y dotar de infraestructura a la población para satisfacer las necesidad es energéticas \n básicas entre las que se incluyen el calentamiento de agua, la cocción de alimentos, la \n refrigeración, la iluminación, entre otros; \n IX. Promover la Transición Energética y el Aprovechamiento Sustentable de la Energía entre los \n sectores econó micos del país, manteniendo y promoviendo la competitividad de los sectores \n productivos en los sectores de consumo final, así como en toda la cadena de producción de \n energía, incluyendo su transformación; \n X. Promover el Aprovechamiento Sustentable de la En ergía y de los recursos renovables, la \n economía circular y el aprovechamiento de los residuos para fines energéticos; \n XI. Establecer los mecanismos de coordinación, supervisión y verificación del cumplimiento de esta \n Ley y las sanciones correspondientes al incumplimiento de ésta, y \n XII. Apoyar el cumplimiento de las metas del país con respecto a la generación de electricidad \n provenientes de fuentes de Energía Limpia y a la reducción de Emisiones de Gases y Compuestos \n de Efecto Invernadero.","tipo_articulo":"ordinario","titulo_nombre":"Disposiciones Generales","capitulo_nombre":null,"seccion_nombre":null,"orden":2},{"id":"f3286a77-34de-419b-9dfa-a1a19a514950","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 3. -","contenido":"Para efectos de la interpretación y aplicación de la presente Ley, se deben entender los conceptos y \n las definiciones, en singular o plural, previstas en la Ley del Sector Eléctrico, la Ley del Sector Hidrocarburos, la Ley \n de Biocombustibles, la Ley de Geoterm ia y en las siguientes definiciones: \n I. Aprovechamiento Sustentable de la Energía: El uso óptimo de la energía y que contribuya a la \n conservación de los recursos energéticos y del medio ambiente en todos los procesos y \n actividades para su exploración, extr acción, explotación, producción, transformación, \n acondicionamiento, distribución, almacenamiento y consumo, e incluye la Eficiencia Energética \n como uno de los principales mecanismos para lograrlo; \n II. Cogeneración: Generación de energía eléctrica producida de manera conjunta con vapor u otro tipo \n de energía térmica secundaria útil o ambos; producción directa o indirecta de energía eléctrica \n mediante la energía térmica no aprovechada en los procesos, o generación directa o indirecta de \n energía eléctrica cuan do se utilicen combustibles producidos en los procesos industriales; \n III. Cogeneración Eficiente: La energía generada por centrales de Cogeneración, en términos de los \n criterios generales emitidos por la Secretaría, los criterios técnicos y metodologías em itidos por la \n Comisión Nacional de Energía y las metodologías de Emisiones establecidas por la Secretaría de \n Medio Ambiente y Recursos Naturales; \n IV. Consejo: Consejo de Planeación Energética; \n V. Contaminantes: Los referidos en la Ley General del Equilibri o Ecológico y la Protección al \n Ambiente y la Ley General de Cambio Climático; \n VI. CONUEE: Comisión Nacional para el Uso Eficiente de la Energía; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 3 de 23 \n VII. Eficiencia Energética: Todas las acciones que conlleven a una reducción, económicamente viable, \n de la cant idad de energía que se requiere para satisfacer las necesidades energéticas de los \n servicios y bienes que demanda la sociedad, asegurando un nivel de servicio igual o superior; \n VIII. Emisiones: Liberación de Gases de Efecto Invernadero o sus precursores y aerosoles a la \n atmósfera, incluyendo en su caso compuestos de efecto invernadero, en una zona y un periodo de \n tiempo específicos; \n IX. Energías Limpias: Son aquellas fuentes de energía y procesos de generación de energía de bajas \n emisiones, incluidos los de finidos como tales en la Ley del Sector Eléctrico; \n X. Energías Renovables: Aquellas cuya fuente reside en fenómenos de la naturaleza, procesos o \n materiales susceptibles de ser transformados en energía aprovechable que se regeneran \n naturalmente o con capaci dad de regeneración a escala del tiempo del ser humano. Se consideran \n fuentes de Energías Renovables las que se enumeran a continuación: \n a ) El viento tanto en zonas terrestres como marinas; \n b ) La radiación solar, en todas sus formas; \n c ) El movimiento del a gua en cauces naturales o en aquellos artificiales con embalses ya \n existentes; \n d ) La energía oceánica en sus distintas formas, como los provenientes de las mareas, del \n gradiente térmico marino, de las corrientes marinas superficiales o submarinas, de olas, \n del gradiente de concentración de sal y cualquier otra forma de energía aprovechable \n del mar; \n e ) La energía que se obtiene mediante el aprovechamiento del calor interno de la tierra, y \n f ) Los energéticos que determine la Ley de Biocombustibles; \n XI. Energí as Fósiles: Aquellas que provienen de la combustión de materiales y sustancias en estado \n sólido, líquido o gaseoso que contienen carbono, y cuya formación ocurrió a través de procesos \n geológicos o fueron obtenidos a partir de estas; \n XII. Estrategia: Estrat egia Nacional de Transición Energética; \n XIII. Externalidades: Los impactos positivos o negativos que genera la provisión de un bien o servicio y \n que afectan o que pudieran afectar a una tercera persona. Las Externalidades ocurren cuando el \n costo pagado por un bien o servicio es diferente del costo total de los daños y beneficios en \n términos económicos, sociales, ambientales y a la salud, que involucran su producción y consumo; \n XIV. Generación Limpia Distribuida: Generación de energía eléctrica que, en los t érminos de la Ley del \n Sector Eléctrico, cumple con las siguientes características: \n a ) Se realiza por un generador exento de permiso; \n b ) Se realiza en una Central Eléctrica que se encuentra interconectada a un circuito de \n distribución que contenga una alta concentración de Centros de Carga, en los términos de las \n Reglas del Mercado, y \n c ) Se realiza a partir de Energías Limpias. \n XV. Hidrógeno Renovable: Aquel producido mediante el uso de energía renovable o electricidad \n producida con fuentes renovables; \n XVI. Justicia Energética: Acciones o Estrategias encaminadas a reducir la Pobreza Energética, las \n desigualdades sociales y de género en el uso de la energía e impulsar el desarrollo regional y la \n prosperidad compartida mediante el acceso a energía e infraestruc tura energética confiable, \n asequible, segura y limpia para la atención de necesidades básicas, la reducción de impactos en la \n salud y el medio ambiente. Incluye también la ampliación de espacios de participación inclusiva, \n principalmente de los pueblos ori ginarios, en las cadenas productivas locales de los proyectos \n energéticos; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 4 de 23 \n XVII. Ley: Ley de Planeación y Transición Energética; \n XVIII. PLADESE: El Plan de Desarrollo del Sector Eléctrico; \n XIX. PLADESHi: El Plan de Desarrollo del Sector Hidrocarburos; \n XX. PLATEASE: Plan para la Transición Energética y el Aprovechamiento Sustentable de la Energía; \n XXI. Pobreza Energética: Situación que ocurre cuando en una vivienda no se alcanza a satisfacer una o \n más necesidades energéticas básicas, como son el calentamient o de agua, cocción y conservación \n de alimentos e iluminación, debido a sus condiciones de ingresos y carencias sociales; \n XXII. Reglamento: Reglamento de la Ley de Planeación y Transición Energética; \n XXIII. Sector Energético: Se refiere a las actividades en materia de electricidad e hidrocarburos reguladas \n en la Ley del Sector Eléctrico y la Ley del Sector Hidrocarburos respectivamente, así como aquellas \n establecidas en la Ley de Biocombustibles y de la Ley de Geotermia, y cualquier otra que \n correspondan a l a Secretaría y sus organismos sectorizados, de acuerdo con la Ley Orgánica de la \n Administración Pública Federal; \n XXIV . Secretaría: Secretaría de Energía; \n XXV. Sistema Nacional de Información Energética: Sistema integrado de información energética que \n admin istra la información de la Secretaría y sus organismos sectorizados; \n XXVI. Tecnologías Limpias: Almacenamiento eléctrico, Hidrógeno, Rebombeo, Captura y \n almacenamiento de dióxido de carbono y las usadas para generar Energía limpia y las que \n determine la Se cretaría; \n XXVII. Transición Energética: Modificación del sistema energético que consiste en la migración de un \n sistema basado en Energías Fósiles hacia uno sustentado preponderantemente en Energías \n Renovables y de bajas Emisiones, y \n XXVIII. Usuario de Patr ón de Alto Consumo: Persona física o moral que cumpla con los criterios que \n establezca la CONUEE con relación a su nivel de consumo de energía.","tipo_articulo":"ordinario","titulo_nombre":"Disposiciones Generales","capitulo_nombre":null,"seccion_nombre":null,"orden":3},{"id":"312fe173-64e9-4d6c-84c9-d66ab86819f3","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 4. -","contenido":"La interpretación de esta Ley, para efectos administrativos, corresponde a la Secretaría. \n La Secret aría, la CONUEE, la Comisión Nacional de Energía y el Centro Nacional de Control de Energía, en el \n ámbito de sus atribuciones, pueden emitir las disposiciones de carácter general que sean necesarias para la \n aplicación de lo dispuesto en esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"Disposiciones Generales","capitulo_nombre":null,"seccion_nombre":null,"orden":4},{"id":"1edee6b3-e7ec-4a84-9301-40143d351eb0","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   5. -","contenido":"En lo no previsto por la presente Ley, se deben aplicar de manera supletoria las disposiciones \n contenidas en la Ley del Sector Eléctrico, la Ley del Sector Hidrocarburos, la Ley de Biocombustibles, la Ley de \n Geotermia y la Ley Federal del Procedimiento Administrativo. \n TÍTULO SEGUNDO \n De la Planeación del Sector Energético","tipo_articulo":"ordinario","titulo_nombre":"Disposiciones Generales","capitulo_nombre":null,"seccion_nombre":null,"orden":5},{"id":"e20aabf1-e2ab-4708-990b-5fc19992f088","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 6. -","contenido":"El Ejecutivo Federal, por conducto de la Secretaría, la Secretaría de Medio Ambiente y Recursos \n Naturales, la CONUEE, el Centro Nacional de Control de Energía, el Centro Na cional de Control del Gas Natural, la \n Comisión Nacional de Energía, las Empresas Públicas del Estado, el Instituto Mexicano del Petróleo y el Instituto \n Nacional de Electricidad y Energías Limpias, en el ámbito de sus atribuciones, deben ejercer las faculta des \n conferidas por esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":null,"seccion_nombre":null,"orden":6},{"id":"76b5c7c0-3779-413e-b02d-e91c257c4cc1","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 7. -","contenido":"La Secretaría de Medio Ambiente y Recursos Naturales, la CONUEE, el Centro Nacional de Control \n de Energía, el Centro Nacional de Control del Gas Natural, la Comisión Nacional de Energía y las Empresas Públicas \n del Estado, bajo la coordinación de la Secretaría, deben facilitar la implementación de la planeación vinculante en el \n Sector Energético. \n Capítulo I \n De las Autoridades y Organismos","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":null,"seccion_nombre":null,"orden":7},{"id":"780cc8dc-3d74-4661-8419-73c05a13100d","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 8. -","contenido":"Para efectos de esta Ley, corresponde a la Secretaría: \n I. Elaborar y publicar la Estrategia, el Programa Sectorial de Energía, el PLATEASE, el PLADESE, el \n PLADESHi y coordinar su ejecución, así como vigilar el cumplimiento de dichos instrumentos; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 5 de 23 \n II. Promover el cumplimiento de todas las metas de la Estrategia mediante l a formulación y aplicación \n de instrumentos de política pública y la coordinación con las dependencias de la Administración \n Pública Federal, gobiernos locales y otras instancias relevantes, públicas o privadas; \n III. Elaborar y publicar por medios electrónic os el reporte de avance en el cumplimiento de las metas \n establecidas en la Estrategia. Los requisitos para el cumplimiento de esta fracción se deben \n establecer en el Reglamento de la presente Ley; \n IV. Promover el cumplimiento de los compromisos internacion ales que México haya adquirido y cuyo \n cumplimiento esté relacionado directamente con esta Ley y las metas de la Estrategia, en \n condiciones de viabilidad económica y sin menoscabo de la competitividad; \n V. Elaborar y actualizar el Atlas Nacional de Zonas con potencial de Energías Renovables, que debe \n incluir, al menos el contenido actualizado y verificable siguiente: \n a ) Las zonas del país que tengan potencial de Energías Renovables, y \n b ) Las variables geográficas relevantes para el desarrollo de Energías Reno vables. Para \n desarrollar esta información, se cuenta con la colaboración del Servicio Meteorológico \n Nacional, del Instituto Nacional de Estadística y Geografía, las Empresas Públicas del Estado, \n la Comisión Nacional del Agua, entre otras; \n VI. Suscribir con venios y acuerdos de coordinación con los gobiernos de las entidades federativas y, \n en su caso, de los municipios, en el ámbito de sus respectivas competencias en las materias de \n esta Ley; \n VII. Coordinar a sus organismos sectorizados para, entre otros, ase sorar y apoyar técnicamente a las \n entidades federativas y municipios que lo soliciten en el diseño e implementación de proyectos, \n programas o reglamentaciones técnicas locales relacionadas con la Eficiencia Energética, \n Aprovechamiento Sustentable de la Ene rgía, almacenamiento de energía, reducción de Emisiones \n y Energías Limpias; \n VIII. Planear la construcción de las obras de infraestructura del Sector Energético que faciliten el \n desarrollo de proyectos para la Transición Energética y la Generación Limpia Di stribuida en \n condiciones de viabilidad económica y que fomenten el desarrollo social; \n IX. Asegurar la congruencia e integralidad entre los instrumentos de planeación vinculante del Sector \n Energético; \n X. Desarrollar el PLATEASE para el cumplimiento de las m etas de la Estrategia y el Programa \n Sectorial de Energía. La Secretaría puede solicitar a la CONUEE, la Comisión Nacional de Energía \n y sus organismos sectorizados, apoyo técnico para la determinación de las metas; \n XI. Implementar y administrar el Sistema N acional de Información Energética con el apoyo del Consejo \n de Planeación Energética; \n XII. Solicitar información a las dependencias de la Administración Pública Federal, Empresas Públicas \n del Estado, gobiernos locales y otros organismos públicos o privados, así como a particulares, de \n acuerdo con lo establecido en la regulación que, para tal efecto, se emita en el marco del Sistema \n Nacional de Información Energética; \n XIII. Imponer sanciones por el incumplimiento en la entrega de información para el Sistema N acional de \n Información Energética; \n XIV. Administrar los fondos y fideicomisos constituidos por el Gobierno Federal para el cumplimiento de \n la Ley, en términos del presente ordenamiento y su Reglamento; \n XV. Coordinar en las materias de su competencia la sim plificación administrativa con dependencias \n federales; \n XVI. Formular y emitir, en coordinación con Secretaría de Medio Ambiente y Recursos Naturales, las \n metodologías para la cuantificación de las Emisiones por la explotación, producción, \n transformación, d istribución y elaboración de productos intensivos en consumo de energía, así \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 6 de 23 \n como las Emisiones evitadas debido a la incorporación de acciones para la transición energética y \n el Aprovechamiento Sustentable de la Energía; \n XVII. Elaborar, en coordinación con la Secretaría de Hacienda y Crédito Público, la Secretaría de Salud, \n la Secretaría de Medio Ambiente y Recursos Naturales, la Secretaría de Economía y la Comisión \n Nacional de Energía, una metodología para valorar las Externalidades; \n XVIII. Proponer a la S ecretaría de Hacienda y Crédito Público, mecanismos de apoyo o estímulos fiscales \n o financieros, que permitan promover inversiones, acciones, programas o proyectos en materia de \n Eficiencia Energética, integración de sistemas de Energía limpia, Justicia Ene rgética y combate a la \n Pobreza Energética, innovación y desarrollo tecnológico, formación de recursos humanos y \n reducción de Emisiones del Sector Energético. Para el cumplimiento de esta obligación la \n Secretaría puede solicitar el apoyo técnico de sus orga nismos sectorizados; \n XIX. Implementar y promover las mejores prácticas internacionales en la planeación, diseño y ejecución \n de programas y proyectos de Transición Energética y Aprovechamiento Sustentable de la Energía; \n XX. Emitir Normas Oficiales Mexicanas en las materias objeto de esta Ley por si o a través de sus \n organismos sectorizados; \n XXI. Promover la investigación científica, el desarrollo tecnológico y la formación de recursos humanos \n especializados en el Sector Energético; \n XXII. Elaborar por sí mism a o mediante sus organismos sectorizados los estudios e investigaciones para \n la planeación del Sector Energético; \n XXIII. Solicitar a los organismos sectorizados apoyo técnico para la determinación de las metas de la \n Estrategia y la información que requiera para la planeación del Sector Energético, y \n XXIV. Vigilar y supervisar el cumplimiento de la presente Ley y las demás disposiciones que emanen de \n esta e imponer sanciones derivadas de su incumplimiento.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":8},{"id":"f6b0f491-bd9c-483d-ab8d-4daddb8baa87","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 9. -","contenido":"Corresponde a la Secretaría de Medio Am biente y Recursos Naturales: \n I. Diseñar y aplicar, en el ámbito de su competencia y en coordinación con la Secretaría, los \n instrumentos de fomento y de normatividad para prevenir, controlar y remediar la contaminación \n proveniente de la generación y transmi sión de energía eléctrica y de combustibles en lo referente a \n Emisiones de Contaminantes a la atmósfera, incluidos los gases y compuestos de efecto \n invernadero y residuos, en los términos definidos en este ordenamiento; \n II. Realizar y coordinar estudios e investigaciones, en coordinación con la Secretaría, para: \n a ) Determinar las causas y efectos de los problemas ambientales generados por el Sector \n Energético y actividades extractivas asociadas, respecto al aprovechamiento racional y \n sustentable de los recu rsos naturales no renovables, y \n b ) Determinar las mejores prácticas para la prevención y control de la contaminación que \n pudiera generar el Sector de Energético; \n III. Colaborar y coordinarse con la Secretaría para asegurar el intercambio de información y l a \n congruencia de las autorizaciones de estas autoridades para el desarrollo de proyectos del Sector \n Energético, particularmente en las materias de evaluación de impacto ambiental, impacto social y \n manejo de residuos; \n IV. Colaborar y coordinarse con la Secr etaría para asegurar el intercambio de información para la \n simplificación administrativa; \n V. Elaborar estudios de evaluación ambiental estratégica de carácter regional para promover la \n instalación de proyectos de Energías Limpias. \n Para el cumplimiento de lo establecido en esta fracción, la Secretaría de Medio Ambiente y \n Recursos Naturales puede apoyarse de instituciones públicas, privadas, académicas, del sector \n social y de la cooperación internacional; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 7 de 23 \n VI. Compartir los resultados de los estudios de evalu ación ambiental estratégica con la Secretaría para \n que se integre en la planeación del Sector Energético y desarrollar mecanismos para la promoción \n y simplificación de la evaluación de impacto ambiental de los proyectos de Energías Limpias en las \n regiones que determine, en coordinación con la Secretaría; \n VII. En coordinación con la Secretaría, actualizar la línea base de Emisiones de bióxido de carbono \n equivalente del Sector Energético en su conjunto y proyectar la disminución esperada en las \n Emisiones de g ases y compuestos de efecto invernadero en concordancia con el cumplimiento de \n las metas de Energías Limpias y con el cumplimiento de su contribución a las metas establecidas \n en la Ley General de Cambio Climático; \n VIII. Publicar, en conjunto con la Secreta ría un informe de las Emisiones de gases y compuestos de \n efecto invernadero y del resto de los Contaminantes atmosféricos regulados que tenga cada \n instalación del Sector Energético y que tenga una emisión mayor o igual al umbral que derive de la \n Ley Genera l de Cambio Climático en materia de Registro Nacional de Emisiones, para la \n publicación de los instrumentos de planeación; \n IX. Proporcionar a la Secretaría la información sobre consumo final de la energía y las Emisiones \n Contaminantes de los sectores energ ético, industrial y de consumo final, y \n X. Colaborar y coordinarse con la Secretaría en la vigilancia del cumplimiento en materia de \n Emisiones y Eficiencia Energética vinculadas al Sector Energético.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":9},{"id":"b371e023-4bc1-4c47-b0cd-fc750d2ae889","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   10. -","contenido":"La CONUEE es un órgano administrativo desc oncentrado de la Secretaría que cuenta con \n autonomía técnica y operativa. Tiene por objeto promover la Eficiencia Energética y constituirse como órgano de \n carácter técnico en materia de Aprovechamiento Sustentable de la Energía. \n La CONUEE tiene una Direcci ón General, cuya persona titular debe ser designada por la persona titular del \n Ejecutivo Federal a propuesta de la persona titular de la Secretaría de Energía, quien la debe dirigir y representar \n legalmente; adscribir las unidades administrativas de la mis ma; expedir sus manuales; tramitar el presupuesto; \n delegar facultades en el ámbito de su competencia; nombrar y remover al personal, y tener las demás facultades que \n le confieran esta Ley y las demás disposiciones aplicables.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":10},{"id":"debba780-8a73-41e5-8130-abc571cf60b6","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 11. -","contenido":"Corresponde a la CONUEE: \n I. Promover el uso óptimo de la energía, desde su explotación hasta su uso final; \n II. Brindar apoyo técnico a la Secretaría, en el ámbito de su competencia, en la determinación de las \n metas de la Estrategia y los demás instrumentos de planeación, así como los mecanismos para su \n cumplimiento; \n III. Colaborar con la Secretaría para la elaboración del PLATEASE y la Estrategia en las materias de \n su competencia; \n IV. Proponer a la Secretaría las metodologías y procedimientos para cuantificar los beneficio s \n energéticos y económicos que se deriven de las acciones y programas de Eficiencia Energética; \n V. Expedir y verificar disposiciones administrativas de carácter general en materia de Eficiencia \n Energética y de las actividades que incluyen el Aprovechamient o Sustentable de la Energía, de \n conformidad con las disposiciones aplicables y con la aprobación de la Secretaría; \n VI. Expedir, con la aprobación de la Secretaría, las Normas Oficiales Mexicanas en materia de \n Eficiencia Energética; \n VII. Proponer a las depe ndencias la elaboración o revisión de las Normas Oficiales Mexicanas a fin de \n propiciar la Eficiencia Energética; \n VIII. Promover, en conjunto con la Secretaría, la investigación científica y el desarrollo tecnológico en la \n materia de Aprovechamiento Susten table de la Energía, en coordinación con el Instituto Nacional \n de Energías Limpias, el Instituto Mexicano del Petróleo y el Instituto Nacional de Ecología y \n Cambio Climático, en el ámbito de sus respectivas competencias; \n IX. Brindar asesoría técnica para l a instrumentación y operación de programas y acciones de \n Eficiencia Energética en las entidades de la Administración Pública Federal y Empresas Públicas \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 8 de 23 \n del Estado, así como asistir a la Secretaría para la supervisión del cumplimiento de las acciones de \n Ef iciencia Energética; \n X. Suscribir convenios para brindar asesoría y apoyo técnico a las entidades federativas y municipios \n que lo soliciten, para el diseño e implementación de proyectos, programas o reglamentaciones \n técnicas locales relacionadas con la Efi ciencia Energética y el Aprovechamiento Sustentable de la \n Energía; \n XI. Emitir opiniones vinculatorias para las dependencias y entidades de la Administración Pública \n Federal, Empresas Públicas del Estado, y para estados y municipios en programas, proyectos y \n actividades de Aprovechamiento Sustentable de la Energía que utilicen fondos públicos federales; \n XII. Elaborar, publicar y difundir libros, catálogos, manuales, artículos, informes técnicos y material \n audio visual sobre los trabajos que realice en las ma terias de su competencia; \n XIII. Ordenar y ejecutar verificaciones, físicas o remotas, y requerir la presentación de información a las \n personas físicas o morales del sector público o privado que realicen actividades relativas al \n Aprovechamiento Sustentable de la Energía, a fin de supervisar y vigilar, en el ámbito de su \n competencia, el cumplimiento de las disposiciones aplicables; \n XIV. Llevar a cabo los estudios que requiera para conocer elementos tecnológicos y prácticas que \n determinan patrones e intensidad de consumo de energía por uso final y otros segmentos de \n consumo, tipo de usuario, actividad económica y región del país; \n XV. Promover y concertar, con los Usuarios de Patrón de Alto Consumo de energía, la instrumentación \n obligatoria de sistemas de gestió n energética de acuerdo con las disposiciones que para tal efecto \n emita; \n XVI. Promover la creación y fortalecimiento de capacidades de las instituciones públicas y privadas para \n que apoyen y, en su caso, implementen programas y proyectos de Eficiencia Ener gética y \n Aprovechamiento Sustentable de la Energía; \n XVII. Proponer a la Secretaría los criterios para determinar que una persona usuaria cuenta con un \n patrón de alto consumo de energía; \n XVIII. Identificar e implementar las mejores prácticas internacionales en cuanto a programas y proyectos \n de Eficiencia Energética y Aprovechamiento Sustentable de la Energía, y \n XIX. Vigilar e imponer sanciones por el incumplimiento de la presente Ley, en el ámbito de sus \n atribuciones.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":11},{"id":"b637bf54-b3dd-4d5e-80cf-7872934d9af3","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 12. -","contenido":"El Instituto Nacional de E lectricidad y Energías Limpias es un organismo público descentralizado de \n la Administración Pública Federal, con personalidad jurídica, patrimonio propio y autonomía de gestión, sectorizado \n en la Secretaría, de conformidad con las disposiciones aplicables de la Ley Federal de Entidades Paraestatales.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":12},{"id":"73cbbf7b-81d2-4838-9781-50e685395c47","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 13. -","contenido":"El Instituto Nacional de Electricidad y Energías Limpias tiene por objeto: \n I. Coordinar y realizar estudios y proyectos de investigación científica o tecnológica con instituciones \n académicas, de i nvestigación, públicas o privadas, nacionales o extranjeras en materia de energía, \n energía eléctrica, Energías y Tecnologías Limpias, Energías Renovables, Eficiencia Energética, \n reducción de Emisiones Contaminantes generadas en el Sector Energético, susten tabilidad, \n sistemas de transmisión, distribución y almacenamiento de energía, y sistemas asociados con la \n operación del Sistema Eléctrico Nacional; \n II. Brindar insumos técnicos y científicos a la Secretaría en la materia de su competencia para la \n planeació n y la formulación de políticas; \n III. Brindar servicios técnicos y científicos, en las materias de su competencia, a las dependencias, \n organismos y Empresas Públicas del Estado y al sector privado, y \n IV. Las demás que le señale su regulación orgánica. \n Artí culo 14. - Para efectos de esta Ley, corresponde a la Comisión Nacional de Energía: \n I. Coadyuvar a la identificación de las zonas de mayor potencial de Energías Limpias; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 9 de 23 \n II. Expedir los modelos de contrato de interconexión y de contraprestación para la Gene ración Limpia \n Distribuida; \n III. Elaborar y publicar anualmente, en coordinación con la Secretaría de Medio Ambiente y Recursos \n Naturales, el factor de emisión del Sistema Eléctrico Nacional; \n IV. Brindar apoyo técnico a la Secretaría para la determinación d e las metas que se deben establecer \n en los instrumentos de planeación; \n V. Proporcionar a la Secretaría la información que ésta le solicite para la planeación del Sector \n Energético, y \n VI. Vigilar e imponer sanciones por el incumplimiento de la presente Ley, en el ámbito de sus \n atribuciones.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":13},{"id":"dde2713e-c536-4408-a47c-0f98cf4c9ad4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 15. -","contenido":"Corresponde al Centro Nacional de Control de Energía: \n I. Administrar el acceso a la Red Nacional de Transmisión y las Redes Generales de Distribución de \n las Centrales Eléctricas, incluyendo las Energías Limp ias, acorde a la planeación del sector y \n dando prioridad a la Confiabilidad del Sistema Eléctrico Nacional. Debe tomar en consideración las \n acciones en materia de almacenamiento de energía incluidas en el PLATEASE; \n II. Incluir en los programas de ampliació n y modernización para la Red Nacional de Transmisión que \n proponga a la Secretaría, la expansión y equipamiento necesario para el aprovechamiento de los \n recursos ubicados en las zonas con potencial de Energías Renovables, acorde a la planeación del \n Sector Energético, promoviendo el cumplimiento de las metas de la Estrategia en condiciones de \n viabilidad económica, y \n III. Proporcionar a la Secretaría la información que ésta le solicite para la elaboración del PLADESE. \n Capítulo II \n Del Consejo de Planeación Ene rgética","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De las Autoridades y Organismos","seccion_nombre":null,"orden":14},{"id":"ad97191f-dcf5-401c-9653-de84ac35896c","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 16. -","contenido":"El Consejo es el órgano de coordinación y seguimiento de la planeación energética nacional, \n establecida a través de los instrumentos de planeación, así como de la mejora de la información energética requerida \n para dicha planeación. El Consejo se debe reunir al menos dos veces al año y cuando se requiera, para los fines de \n sus atribuciones. \n La Secretaría debe emitir los lineamientos de operación del Consejo.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"Del Consejo de Planeación Ene rgética","seccion_nombre":null,"orden":15},{"id":"cdfa9701-1534-485f-a6f6-c90cecb4dbc4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 17. -","contenido":"El Consejo debe ser presidido por la persona titular de la Secret aría y se integra por: \n I. Una persona secretaria técnica; \n II. Las personas titulares de las Subsecretarías de la Secretaría, y \n III. Una persona representante de cada organismo sectorizado: Petróleos Mexicanos, Comisión \n Federal de Electricidad, Centro Nacio nal de Control del Gas Natural, Centro Nacional de Control de \n Energía, Comisión Nacional de Energía, CONUEE y LitioMX. \n Además, puede haber personas invitadas representantes: Secretaría de Hacienda y Crédito Público; Secretaría \n de Medio Ambiente y Recursos Naturales; Secretaría de Economía; Secretaría de Desarrollo Agrario, Territorial y \n Urbano; Secretaría de Agricultura y Desarrollo Rural; Secretaría de Infraestructura, Comunicaciones y Transportes; \n Secretaría de Ciencia, Humanidades, Tecnología e Innovació n; Secretaría de Bienestar; Instituto Nacional de \n Estadística y Geografía, y de otras instancias públicas o privadas que sean invitadas por la Presidencia del Consejo a \n través de la persona titular de la Secretaría Técnica. \n Las personas invitadas pueden pa rticipar con voz, pero sin voto.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"Del Consejo de Planeación Ene rgética","seccion_nombre":null,"orden":16},{"id":"0207cfb1-6043-45e4-a865-caf266ceefcb","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 18. -","contenido":"Las personas representantes de las dependencias y entidades de la Administración Pública Federal \n deben tener, al menos, el nivel de director general y pueden designar a una persona suplente que debe tener, al \n menos, nivel de dirección. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 10 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"Del Consejo de Planeación Ene rgética","seccion_nombre":null,"orden":17},{"id":"e8ed0a1f-fe4a-476c-b469-3ddedbd9a62f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 19. -","contenido":"La persona titular de la Presidencia del Consejo, por sí misma o a través de la Secretaría Técnica, \n puede invitar a las sesiones del Consejo a otras autoridades federales, de las entidades federativas y municipales, \n así como a personas físicas y organizaciones relacionadas con la Transición Energética, lo anterior, cuando se \n estime conveniente por la naturaleza de los asuntos a tratar, quienes deben acudir en calidad de personas invitadas \n que participan con voz, pero sin voto.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"Del Consejo de Planeación Ene rgética","seccion_nombre":null,"orden":18},{"id":"87aa68e6-2efb-4e4c-9e47-05a4e789fdce","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 20. -","contenido":"El Consejo tiene las atribuciones siguientes. \n I. En materia de planeación: \n a ) Coordinar y dar seguimiento a la planeación energética nacional; \n b ) Opinar sobre la política energética, programas y acciones para dar cumplimiento a la \n planeación energética establecida en los instrumentos de planeación de esta Ley; \n c ) Proponer adecuaciones y mejoras a los documentos de planeación energética para asegurar \n una mayor coordinación y seguimiento; \n d ) Vigilar y dar seguimiento a la ejecución de los instrumentos de planeación de esta Ley y sus \n metas; \n e ) Conformar comités dentro del Consejo que se consideren necesarios para coadyuvar a la \n coordinación y seguimiento de la planeación energética nacional, y \n f ) Proponer a la Secretaría programas y pro yectos de Transición Energética para la planeación \n del Sector Energético; \n II. En materia de información energética: \n a ) Coordinar y dar seguimiento a las acciones que se determinen para la mejora y acceso de la \n información para la elaboración de la planeaci ón energética nacional, el Balance Nacional de \n Energía y el Sistema Nacional de Información Energética; \n b ) Conformar comités que se consideren necesarios que ayuden a la coordinación y seguimiento \n de la mejora y acceso de la información para la elaboración de la planeación energética \n nacional; \n c ) Emitir recomendaciones para el mejoramiento y acceso de la información para la planeación \n energética nacional, y \n d ) La persona secretaria técnica debe elaborar un reporte anual de mejora y acceso de la \n información para la planeación energética nacional, donde se presentan avances y áreas de \n oportunidad. \n Capítulo III \n De los Instrumentos de Planeación Energética","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"Del Consejo de Planeación Ene rgética","seccion_nombre":null,"orden":19},{"id":"3e0d9d78-e421-452a-ada1-5054c39f3869","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 21. -","contenido":"Son instrumentos de planeación del Sector Energético los siguientes: \n I. La Estrategia; \n II. Pr ograma Sectorial de Energía; \n III. El PLATEASE; \n IV. El PLADESE, y \n V. El PLADESHi. \n La Secretaría debe elaborarlos y publicarlos en términos de la Ley de Planeación y conforme se establezca en el \n Reglamento.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":20},{"id":"f78f2123-b224-41df-a3b1-cbb7b767634a","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 22. -","contenido":"Sin perjuicio del régimen especial ap licable a las Empresas Públicas del Estado, la Secretaría de \n Hacienda y Crédito Público debe consolidar en el proyecto de Presupuesto de Egresos de la Federación, las \n provisiones de recursos del sector público necesarios para cumplir con los objetivos prio ritarios establecidos en la \n Estrategia y en los otros instrumentos de planeación. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 11 de 23 \n La Secretaría de Hacienda y Crédito Público debe consultar con la Secretaría los lineamientos y criterios para \n identificar estos recursos en el anexo presupuestal correspondi ente.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":21},{"id":"eacb779d-7bf5-4d2c-912b-88a59ad25bce","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 23. -","contenido":"Los instrumentos de planeación establecidos en el artículo 21 de la presente Ley, así como sus \n actualizaciones se deben publicar en el Diario Oficial de la Federación, previa aprobación por parte de la persona \n titular de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":22},{"id":"c05dd687-17d4-483c-89f0-7803eefadc89","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 24. -","contenido":"La Estrategia constituye el instrumento rector de la política nacional en el mediano y largo plazo en \n materia de Transición Energética, Aprovechamiento Sustentable de la Energía, Eficiencia Energética, Energías \n Limpias, Justicia Energética, i nnovación, desarrollo tecnológico y formación de recursos humanos del sector \n energético. Los elementos mínimos que debe establecer son: \n I. Un diagnóstico del Sector Energético; \n II. Metas; \n III. Escenarios de mediano y largo plazo; \n IV. Responsabilidades para el cumplimiento de metas, y \n V. Líneas de acción estratégicas. \n La Estrategia se debe publicar en el Diario Oficial de la Federación dentro del primer año de la Administración \n Presidencial y debe actualizarse cada tres años, particularmente en el componente de mediano plazo, para asegurar \n la coherencia e integralidad de los planes de Desarrollo del Sector Eléctrico y del Sector Hidrocarburos. \n El diagnóstico del Sector Energético a que se refiere la fracción I de este artículo debe incluir, al menos, la \n produ cción y el consumo final de la energía y sus Emisiones.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":23},{"id":"b52f4836-bc8f-4cb5-8c26-0ff80c55092a","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 25. -","contenido":"Los escenarios de largo plazo tienen un horizonte al menos de 30 años y los de mediano plazo de \n 15 años. \n La Estrategia debe incluir, al menos, las metas de Energías Renovables y demás En ergías Limpias, Eficiencia \n Energética, reducción de la Pobreza Energética, electrificación de los usos finales de la energía y reducción de \n Emisiones Contaminantes que deben reflejar las aportaciones del Sector Energético a los compromisos en materia \n de ca mbio climático de México.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":24},{"id":"1652aafc-2a00-411c-9d5d-1df8bfb54d3d","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 26. -","contenido":"Las metas de Energías Renovables y demás Energías Limpias establecidas en la Estrategia, deben \n constituir porcentajes mínimos en relación con el total de generación de electricidad en México.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":25},{"id":"dd6805aa-f558-4501-a090-2305d9a2e14d","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 27. -","contenido":"La Secreta ría, la Secretaría de Hacienda y Crédito Público, la Secretaría de Medio Ambiente y \n Recursos Naturales, la Comisión Nacional de Energía y la CONUEE, en el ámbito de sus atribuciones, deben \n promover que existan las condiciones legales, regulatorias y fiscal es para facilitar el cumplimiento de las metas y sus \n disposiciones reglamentarias para todos los integrantes del Sector Energético.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":26},{"id":"1ce61fd3-fab7-4402-845c-23f76c271f7f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   28. -","contenido":"El PLATEASE es el documento para la planeación de la Transición Energética y el \n Aprovechamiento Sustentable de la Energía, con un horizonte de 15 años, que debe establecer las actividades, \n programas y proyectos derivados de la Estrategia durante el período de encargo del Ejecutivo Federal.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":27},{"id":"94efb32e-a5db-4c05-bc70-37472f9256ad","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 29. -","contenido":"El PLATEASE se actualiza anualmente y cuenta con los siguient es elementos: \n I. Las metas de Energías Renovables y demás Energías Limpias, Eficiencia Energética y reducción \n de la Pobreza Energética, y las demás señaladas en la Estrategia, que correspondan al período de \n encargo del Ejecutivo Federal; \n II. Las acciones, proyectos y actividades conforme a la Estrategia para alcanzar sus metas en \n condiciones de viabilidad económica y social, así como el detalle de su instrumentación; \n III. Los programas que, a través de las dependencias y entidades de la Administración Públi ca \n Federal, puedan fomentar el Aprovechamiento Sustentable de la Energía; \n IV. Las acciones de Transición Energética, Aprovechamiento Sustentable de la Energía, Eficiencia \n Energética, mejoramiento de combustibles para el uso de la energía en todos los secto res, \n sustitución de combustibles fósiles y la electromovilidad social y particular; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 12 de 23 \n V. Las acciones en materia de investigación, desarrollo tecnológico, innovación y formación de \n recursos humanos en áreas prioritarias en materia de Energías Renovables y de más Energías \n Limpias, Aprovechamiento Sustentable de la Energía, Eficiencia Energética y reducción de la \n Pobreza Energética; \n VI. Acciones y proyectos en materia de redes inteligentes, almacenamiento de energía, \n biocombustibles e hidrógeno renovable; \n VII. A cciones en materia de reducción de fugas y de venteo de metano y el aprovechamiento \n energético de su captura; \n VIII. Acciones y programas para desarrollar la exploración y explotación de áreas geotérmicas y otras \n medidas para impulsar el desarrollo de largo plazo de la energía geotérmica; \n IX. Acciones de mejora y actualización de las normas de Eficiencia Energética y etiquetado de \n Eficiencia Energética adherido a los productos o empaques de estos, y \n X. Otras acciones y programas para promover la sostenibilid ad del Sector Energético.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":28},{"id":"8d77743e-e52a-4a1b-9c06-7cb9ff70dd8e","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 30. -","contenido":"El PLATEASE debe identificar, evaluar, diseñar, innovar, establecer e instrumentar estrategias, \n acciones y proyectos en materia de redes eléctricas inteligentes y almacenamiento de energía.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":29},{"id":"af232b73-1448-4ab9-9618-a8aa5b7a8df2","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 31. -","contenido":"El PLADESHi es el documento del desarrollo y modernización de la infraestructura del Sector \n Hidrocarburos con un horizonte de 15 años, que es elaborado y publicado por la Secretaría, con el apoyo de \n Petróleos Mexicanos, Centro Nacional de Control del Gas Natural y la Comisión Nacional de Energía, así como con \n los organismos públicos y privados que determine la Secretaría. \n El PLADESHi se debe actualizar anualmente y debe contar con las características siguientes: \n I. Incluir un diagnóstico del estado actual que guarda el Sector Hidrocarburos; \n II. Ser consistente con la Estrategia; \n III. Ser consistente con el Plan Nacional de Desarrollo, el Programa Sectorial de Energía y el \n PLATEASE; \n IV. Contar con escenarios con un horizonte de 15 años, cartera de proyectos y programas d e inversión \n de 3 a 5 años; \n V. Considerar el cambio tendencial en los patrones de demanda energética de los sectores de uso \n final, así como de producción y transformación de la energía; \n VI. Incluir programas de desarrollo de infraestructura en materia de Ex ploración, Extracción, \n Almacenamiento, Transporte y Distribución de Hidrocarburos, Gas Natural, Petrolíferos, \n Petroquímica, Eficiencia Energética, sostenibilidad y Transición Energética, y \n VII. Las demás que deriven de la Ley del Sector Hidrocarburos y dem ás legislación aplicable. \n La Secretaría, la Comisión Nacional de Energía, otros organismos públicos sectorizados y la Secretaría de Medio \n Ambiente y Recursos Naturales, en el ámbito de sus atribuciones, deben considerar el PLADESHi en el otorgamiento \n de pe rmisos y otras autorizaciones de modo que la inversión pública y privada, así como la operación en el Sector \n Energético, contribuyan a las metas de mediano y largo plazo establecidas en el PLADESHi y la Estrategia. \n Petróleos Mexicanos debe considerar la Es trategia y el PLADESHi, como parte de los elementos rectores de su \n plan estratégico.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":30},{"id":"6edded5a-5d0c-4a34-aa41-608fdd38fe85","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 32. -","contenido":"El PLADESE es el documento del desarrollo y modernización de la infraestructura del Sector \n Eléctrico con un horizonte de 15 años, que es elaborado y publicad o por la Secretaría, con el apoyo de la Comisión \n Federal de Electricidad, el Centro Nacional de Control de Energía y la Comisión Nacional de Energía, así como con \n los organismos públicos y privados que determine la Secretaría. \n El PLADESE debe actualizarse anualmente y contar con las características siguientes: \n I. Incluir un diagnóstico del estado actual que guarda el Sector Eléctrico; \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 13 de 23 \n II. Ser consistente con la Estrategia; \n III. Ser consistente con el Plan Nacional de Desarrollo, el Programa Sectorial de Ene rgía y el \n PLATEASE; \n IV. Contar con escenarios con un horizonte de 15 años, y programas de inversión de 3 a 5 años; \n V. Considerar el cambio tendencial en los patrones de demanda energética de los sectores de uso \n final, así como de producción y transformació n de la energía; \n VI. Incluir programas vinculantes de inversión pública en materia de instalación, modernización y retiro \n de centrales eléctricas, de la expansión de la Red Nacional de Transmisión, de las Redes \n Generales de Distribución, Servicios Conexos, Eficiencia Energética, sostenibilidad y Transición \n Energética, y \n VII. Las demás que deriven de la Ley del Sector Eléctrico y demás legislación aplicable. \n La Secretaría, la Comisión Nacional de Energía, los otros organismos públicos sectorizados en energía y la \n Secretaría de Medio Ambiente y Recursos Naturales, en el ámbito de sus atribuciones, deben considerar el \n PLADESE en el otorgamiento de permisos y otras autorizaciones de su competencia, de modo tal que la inversión \n pública y privada, así como la oper ación del Sector Energético, contribuyan a las metas de mediano y largo plazo \n establecidas en el PLADESE y la Estrategia. \n La Comisión Federal de Electricidad debe considerar la Estrategia y el PLADESE, como parte de los elementos \n rectores de su plan estrat égico. \n Capítulo IV \n De la Información Energética \n Sección I \n Del Sistema Nacional de Información Energética","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De los Instrumentos de Planeación Energética","seccion_nombre":null,"orden":31},{"id":"1a61524e-f592-4339-993a-61e5f77fe93b","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 33. -","contenido":"La Secretaría debe administrar el Sistema Nacional de Información Energética con el objeto de \n registrar, organizar, actualizar y difundir la información del Sector Energético. Los requisitos para el cumplimiento de \n este artículo se deben determinar en el Reglamento. \n Para la operación e implementación del Sistema Nacional de Información Energética la Secretaría debe observar \n las recomendacio nes del Consejo y lo establecido en la Ley del Sistema Nacional de Información Estadística y \n Geográfica.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"Del Sistema Nacional de Información Energética","orden":32},{"id":"761a2c6c-ff11-4d70-a115-b33995a4b69a","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 34. -","contenido":"Para la operación e implementación del Sistema Nacional de Información Energética, la Secretaría \n tiene las atribuciones siguientes: \n I. Em itir las disposiciones para la entrega y actualización de información al Sistema Nacional de \n Información Energética; \n II. Publicar la información del Sector Energético, de acuerdo con la política energética nacional; \n III. Integrar al Sistema Nacional de Inf ormación Energética los diferentes sistemas de información del \n Sector Energético; \n IV. Promover acuerdos con otras dependencias de la Administración Pública Federal para compartir \n información estratégica del Sector Energético; \n V. Realizar el análisis de la información del Sistema Nacional de Información Energética o solicitarlo a \n los organismos sectorizados; \n VI. Contratar licencias de software, infraestructura y servicios especializados para la gestión, \n protección y análisis de la información del Sistema Nac ional de Información Energética. Estas \n contrataciones no están sujetas a los procedimientos de contratación de tecnologías de la \n información de la Administración Pública Federal, dado el carácter estratégico de la información, y \n VII. Vigilar el cumplimient o de las disposiciones y establecer sanciones respecto de la entrega de \n información al Sistema Nacional de Información Energética. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 14 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"Del Sistema Nacional de Información Energética","orden":33},{"id":"90bd49f4-280b-479e-8e9f-c246372010d5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 35. -","contenido":"La Secretaría debe elaborar y publicar anualmente el Balance Nacional de Energía con escenarios \n prospectivos de energía que presenta la información de origen y destino de la energía en el territorio nacional del año \n anterior. \n Los escenarios prospectivos del Balance Nacional de Energía y escenarios prospectivos de energía deben tener \n un horizonte de 15 años. \n Sección II \n De la información en materia de Eficiencia Energética","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"Del Sistema Nacional de Información Energética","orden":34},{"id":"dc5d0740-5cc3-43f1-9f2f-62d9143a8c96","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 36. -","contenido":"La CONUEE debe elaborar y publicar un catálogo de los equipos y aparatos que deben incluir de \n forma clara, sencilla y visible para el público la información sobre su consumo energético . Este catálogo incluye a los \n equipos y aparatos cuyo consumo de energía y número de unidades comercializadas sean relevante a consideración \n de la CONUEE. Esta información debe ser visible al público en general y en la página de Internet de la CONUEE, a \n fi n de ayudar a las personas consumidoras a tomar decisiones de compra entre las distintas opciones que existan en \n el mercado. \n La CONUEE debe proponer a la Secretaría las disposiciones reglamentarias donde establezcan el detalle de la \n información sobre el co nsumo energético que debe incluirse en los equipos y aparatos referidos en este artículo, así \n como la forma en la que ésta se incluya.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":35},{"id":"6bc6d556-de90-45aa-91d2-4979b0605bdd","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 37. -","contenido":"La información a que hace referencia el artículo anterior debe presentarse por medio de un \n marcado, estampa do o etiquetas de Eficiencia Energética adherido a los productos o empaques de estos, con el fin \n de ayudar a las personas consumidoras a tomar decisiones de compra entre las distintas opciones que existan en el \n mercado. \n La Secretaría puede exentar de este requisito a los equipos y aparatos que están comprendidos en el campo de \n aplicación de una Norma Oficial Mexicana de Eficiencia Energética vigente y que cuenten con el certificado \n correspondiente. Para ello debe solicitar a la CONUEE un estudio que demuest re la conveniencia de la exención.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":36},{"id":"a917ab23-ac28-49d2-b63f-d3d2f33bb424","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 38. -","contenido":"La Comisión Federal de Electricidad y los suministradores de gas natural deben incluir en sus \n recibos de pago o facturas, leyendas para incentivar el uso eficiente de la energía y sus beneficios en la preser vación \n del medio ambiente, así como de difusión de los programas públicos de Aprovechamiento Sustentable de la Energía \n y Eficiencia Energética. Las leyendas deben ser propuestas por la CONUEE.","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":37},{"id":"ea53ada6-8dc1-4f33-b63b-43bcbba640d2","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 39. -","contenido":"Cada tres años, la CONUEE debe realizar estudios sobre la eficacia y ahorros de las Normas \n Oficiales Mexicanas, programas de información y etiquetado en materia de Eficiencia Energética. \n Estos estudios pueden realizarse por terceros independientes o a través de mecanismos internos que permitan la \n imparci alidad del análisis. \n A partir de las conclusiones de dichos estudios, la CONUEE debe realizar las modificaciones pertinentes para \n mejorar su eficacia e impacto entre los consumidores, previa autorización de la Secretaría. \n TÍTULO TERCERO \n De la Transición En ergética y la reducción de la Pobreza Energética \n Capítulo I \n Del Financiamiento","tipo_articulo":"ordinario","titulo_nombre":"De la Planeación del Sector Energético","capitulo_nombre":"De la Información Energética","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":38},{"id":"7db07a1c-1890-48ba-91ad-9d55018befe4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 40. -","contenido":"Los recursos necesarios para que la Administración Pública Federal cumpla con las obligaciones \n que establece esta Ley deben provenir del Presupuesto de Egresos de la Federación, el Mercado Eléctrico \n Mayorista, el Fondo Mexicano del Petróleo para la Estabilización y el Desarrollo, de los instrumentos financieros y \n económicos disponibles para obras y servicios públicos y demás instrumentos que se establezcan para tale s fines.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":39},{"id":"77a60432-51cf-4ceb-8d3e-8b41c9f04d7f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 41. -","contenido":"Los recursos que se destinen para el cumplimiento de los objetivos de esta Ley, deben impulsar el \n desarrollo tecnológico, Transición Energética y Justicia Energética. \n Los recursos públicos o privados asignados con base en esta Ley de ben ser ejercidos de acuerdo con los \n principios de honestidad, legalidad, productividad, eficiencia, eficacia, transparencia gubernamental y máxima \n publicidad, y deben estar sujetos al monitoreo, reporte y evaluación de su desempeño y efectividad. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 15 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":40},{"id":"5b3f3080-bd79-4dba-ba12-7b92e41f17e4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   42. -","contenido":"El Ejecutivo Federal debe instrumentar políticas y medidas para facilitar apoyos financieros, \n económicos y de mercado que se destinen al cumplimiento de los fines de esta Ley. \n Capítulo II \n Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":41},{"id":"b0f3627d-54fa-4bb4-8eae-f80b54d52c07","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   43. -","contenido":"La Secretaría debe administrar y coordinar el Fondo para la Transición Energética y el \n Aprovechamiento Sustentable de la Energía. \n El patrimonio financiero del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía \n debe actualizarse anualmente por la variación estimada del Índice Nacional de Precios al Consumidor. El monto del \n patrimonio del Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía que se incluyan \n en el Presupuesto de Egresos de la Federación para el ejercicio fiscal correspondiente, puede modificarse en función \n de la cartera de proyectos susceptibles de recibir apoyos de dicho fondo, que cumpla con el propósito de potenciar el \n financiamiento disponibl e para la Eficiencia Energética, las Tecnologías Limpias, la Generación Limpia Distribuida, el \n aprovechamiento de las Energías Renovables y el combate a la Pobreza Energética. \n De conformidad con sus reglas de operación, la asignación y distribución de recu rsos provenientes del fondo a \n que se refiere este Capítulo debe procurar un reparto equilibrado entre propuestas de Energías Limpias y propuestas \n de Eficiencia Energética.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":42},{"id":"254aeb0e-a214-4a4f-a53d-e6d6ec56193f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 44. -","contenido":"Con el fin de potenciar el financiamiento disponible para los propósit os establecidos en el artículo \n anterior, los recursos del Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía \n pueden ser de carácter recuperable y no recuperable, incluyendo el otorgamiento de garantías de crédito u otro tipo \n de apoyos financieros para los proyectos que sean aprobados, según se establezca en sus reglas de operación.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":43},{"id":"bdcb4ff0-010f-4960-9cbc-a82121c3323f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 45. -","contenido":"La Secretaría debe utilizar procesos competitivos para asegurar que los recursos se asignen a los \n proyectos que ofrezcan mayores ben eficios por monto invertido. Los recursos otorgados deben ser los mínimos \n necesarios para dar viabilidad a los proyectos, tomando en consideración los otros ingresos y estímulos que puedan \n recibir. Preferentemente la implementación se debe hacer a través d e entidades públicas.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":44},{"id":"bb0ee218-d847-45ec-a745-a3bee84a2ac4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 46. -","contenido":"El Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía debe contar \n con un órgano colegiado integrado de conformidad con lo establecido en el contrato correspondiente.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":45},{"id":"d1ea3ab9-3f4e-4a31-8d45-794f7e7af313","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 47. -","contenido":"Sin perj uicio de otras facultades que les correspondan, el órgano colegiado del Fondo para la \n Transición Energética y el Aprovechamiento Sustentable de la Energía tiene las funciones siguientes: \n I. Emitir las reglas para la operación del fondo correspondiente y ac tualizarlas cuando así se \n requiera, incluyendo las funciones de administración, asignación y distribución de los recursos con \n el fin de cumplir las obligaciones de esta Ley, promover los objetivos de la Estrategia y los demás \n instrumentos de planeación, y \n II. Convocar a la presentación de propuestas a ser financiadas por el Fondo para la Transición \n Energética y el Aprovechamiento Sustentable de la Energía.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":46},{"id":"318584be-e6be-4beb-be63-467352bc19b4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 48. -","contenido":"Las personas solicitantes que reúnen los requisitos solicitados por el Fondo para la Tra nsición \n Energética y el Aprovechamiento Sustentable de la Energía, pueden ser sujetas para recibir recursos conforme a lo \n señalado en esta Ley y a sus reglas de operación. \n Las entidades públicas deben tener preferencia de asignación de recursos y, en segun do término, las entidades \n privadas con órganos de gobierno cuya decisión mayoritaria sea del sector público y organizaciones sin fines de \n lucro. \n Capítulo III \n Del Fondo de Servicio Universal Energético","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":47},{"id":"872268f3-b919-4811-95d2-0d4fd26d58e6","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 49. -","contenido":"El Fondo de Servicio Universal Energético , debe ser administrado y coordinado por la Secretaría y \n tiene como meta financiar acciones de cobertura eléctrica para las poblaciones que aún no tienen acceso a la \n electricidad, la Justicia Energética y la reducción de la Pobreza Energética. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 16 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":48},{"id":"29bf7152-dee8-4a36-98a8-6d875492d1ed","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 50. -","contenido":"El Fondo de Servicio Universal Energético tiene por objeto la provisión de infraestructura que dote \n de acceso a la electricidad a personas usuarias domésticas que aún no cuenten con servicio eléctrico, contribuir a \n reducir la Pobreza Energética, así como el suministro de equipos eficientes o que aprovechen energías renovables \n para la preparación de alimentos, refrigeración, calentamiento de agua, iluminación y otros que ayuden a satisfacer \n las necesidades energéticas básicas en comunidades rurales y zonas urbanas marginadas. Se pueden apoyar a \n instancias públicas de servicios básicos como centros de salud, educación o seguridad. \n Se deben implementar esquemas para la supervisión del funcionamiento de los equipos y sistemas instalados y \n proporcionar mantenim iento en la medida de lo posible.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":49},{"id":"9b0d5b5f-110d-4dff-9807-5e4090d55e12","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 51. -","contenido":"El Fondo de Servicio Universal Energético se integra, en los términos previstos por la Ley del Sector \n Eléctrico y la Ley del Sector Hidrocarburos, por lo siguiente: \n I. Recursos por el excedente de ingresos qu e resulte de la gestión de pérdidas técnicas del Mercado \n Eléctrico Mayorista; \n II. Donativos nacionales o internacionales de terceras personas para el cumplimiento de sus \n objetivos; \n III. Por los montos de las multas y sanciones que sean impuestas por la Sec retaría y la Comisión \n Nacional de Energía, a través del proceso de facturación y cobranza del Mercado Eléctrico \n Mayorista, y \n IV. Por los montos de las multas y sanciones que sean impuestas y cobradas a las personas titulares \n de los permisos de distribución y comercialización de gas natural y petrolíferos.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":50},{"id":"ba26f6b0-4fd9-40fd-b9d1-e83d4383c962","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 52. -","contenido":"Los apoyos otorgados se deben asignar en apego a los principios de honestidad, legalidad, eficacia, \n eficiencia, transparencia y productividad buscando siempre la máxima publicidad y difusión de sus acciones.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":51},{"id":"b2081544-fc4a-47f0-aee3-b96ead50b458","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 53. -","contenido":"El Fondo de Servicio Universal Energético debe contar con un órgano colegiado como su máxima \n autoridad, integrado por personas servidoras públicas de la Secretaría y de la Secretaría de Bienestar. Los \n lineamientos de conforma ción y operación del fondo deben ser emitidos por la Secretaría. \n El órgano colegiado a que se refiere este artículo puede contar con el apoyo técnico y con fines de consulta de \n aquellas entidades que requiera para la consecución de sus objetivos. \n Capítulo IV \n De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":52},{"id":"d15e7a41-cfeb-47fd-97d6-a2c26085f9d3","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 54. -","contenido":"Los recursos para la innovación, desarrollo tecnológico y formación de recursos humanos, deben \n ser administrados y coordinados por la Secretaría, y tiene n como meta el financiamiento de proyectos de \n investigación científica, desarrollo tecnológico, innovación y formación de recursos humanos enfocados en temas de \n aprovechamiento óptimo de hidrocarburos, Transición Energética y Aprovechamiento Sustentable de la Energía.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":53},{"id":"13cc1d9c-d7d2-4b6e-af8b-234343b52dcb","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 55. -","contenido":"La Secretaría debe administrar los recursos siguientes: \n I. Los que se integran, en los términos previstos por la Ley Federal de Presupuesto y \n Responsabilidad Hacendaria, con recursos provenientes del Fondo Mexicano del Petróleo p ara la \n Estabilización y el Desarrollo; \n II. Los provenientes de donativos nacionales o internacionales de terceras personas para el \n cumplimiento de sus objetivos, y \n III. Otros recursos provenientes de aportaciones determinadas por la Secretaría de Hacienda y Crédito \n Público.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":54},{"id":"ec3448dc-7e50-4aa0-a53f-667441de1a42","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 56. -","contenido":"Los recursos en materia de hidrocarburos se deben dedicar a mejorar la eficiencia de la exploración, \n extracción y refinación de hidrocarburos, así como la producción de petroquímicos. \n Los fondos en materia de sustentabilida d energética se deben dedicar al aprovechamiento de fuentes renovables \n de energía, Eficiencia Energética, uso y mejora de Tecnologías Limpias, diversificación de fuentes primarias de \n energía y electrificación del consumo final. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 17 de 23 \n La Secretaría debe garantiza r que los apoyos, estén alineados con la política pública en materia energética y con \n el propósito de fortalecer las necesidades prioritarias de los organismos públicos, en congruencia con sus planes o \n programas de desarrollo tecnológico, innovación y form ación de recursos humanos.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":55},{"id":"7f876c0d-4c6a-4ab2-9b38-c4de69f94a9b","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 57. -","contenido":"Los apoyos otorgados se deben asignar en apego a los principios de honestidad, legalidad, eficacia, \n eficiencia, transparencia y productividad, buscando siempre la máxima publicidad y difusión de sus acciones y sólo \n se debe otorgar a entidades públicas.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo de Servicio Universal Energético","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":56},{"id":"aa26c670-3720-49b8-9437-36d1fa427b97","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 58. -","contenido":"Cada materia de apoyo debe contar con un órgano colegiado como su máxima autoridad, el cual se \n debe conformar por especialistas en materia de hidrocarburos, electricidad y sustentabilidad energética, en e l ámbito \n que correspondan. \n Adicionalmente, los órganos colegiados pueden contar con el apoyo técnico y con fines de consulta de aquellas \n entidades que requiera para la consecución de sus objetivos. \n Capítulo V \n De la Investigación Científica, la Innovación y el Desarrollo Tecnológico","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":57},{"id":"244d85a2-55b4-4a10-85c0-584aabdd63d8","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 59. -","contenido":"La Secretaría, con el apoyo de los institutos sectorizados a la Secretaría debe promover la \n investigación aplicada, la innovación, el desarrollo tecnológico y la formación de recursos humanos especializados \n para con tribuir a la Transición Energética y la Justicia Energética, para el cumplimiento de las metas de los \n instrumentos de planeación a partir de, entre otros, los siguientes criterios: \n I. El fomento al desarrollo de nuevos conocimientos nacionales, materiales, técnicas, procesos, \n servicios y tecnologías útiles a la Transición Energética y Aprovechamiento Sustentable de la \n Energía; \n II. La viabilidad técnica, ambiental, financiera, administrativa, social y de ejecución de los proyectos \n para el cumplimiento efecti vo de los instrumentos de planeación, y \n III. La vinculación de los resultados de la investigación científica, la innovación y el desarrollo \n tecnológico nacional con la soberanía energética, la seguridad cibernética, el desarrollo económico \n y social tanto n acional como regional, poniendo especial atención en la generación de empleos. \n Capítulo VI \n De los Certificados de Energías Limpias","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Investigación Científica, la Innovación y el Desarrollo Tecnológico","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":58},{"id":"826caf6a-c205-4c88-bb3e-76fd69fc298b","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 60. -","contenido":"Con el objetivo de fomentar el crecimiento de Energías Limpias a que se refiere la presente Ley y en \n los términ os establecidos en la Ley del Sector Eléctrico, la Secretaría establece criterios para reconocer a los \n generadores de Energía Limpia y para otorgar los Certificados de Energías Limpias. La Secretaría debe emitir las \n disposiciones correspondientes. \n Con el f in de visibilizar la necesidad de respaldo de energía fósil en la operación de las energías limpias dentro \n del Sistema Eléctrico Nacional, las disposiciones referidas en el párrafo anterior deben considerar el nivel de \n emisiones reales de cada tecnología y de cada permisionario. La metodología que la Comisión Nacional de Energía \n emita al respecto debe considerar el uso de respaldo y de servicios conexos y adicionales indispensables para la \n operación de las Energías Limpias en el Sistema Eléctrico Nacional, proporcionados por las Energías Fósiles y debe \n considerar los datos de operación anuales del Sistema Eléctrico Nacional que proporcione el Centro Nacional de \n Control de la Energía.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":59},{"id":"6c960bfe-040c-4b5b-819c-08b70b7a61fe","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 61. -","contenido":"La Comisión Nacional de Energía debe mantener un registro púb lico de Certificados de Energías \n Limpias, el cual debe tener el matriculado de cada certificado, así como la información correspondiente a su fecha de \n emisión e historial de propietarios.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":60},{"id":"ccf3a32f-f265-43b8-b7e7-90dbe1e75ee5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 62. -","contenido":"El funcionamiento del registro debe permitir a los par ticulares la realización de los actos jurídicos \n necesarios para su compra, venta, otorgamiento en garantía o cualquier otra operación que involucre real, virtual o \n jurídicamente el traslado de su propiedad. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 18 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":61},{"id":"176e4c17-a8b4-4e0f-ae29-67c0762c20f5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 63. -","contenido":"El registro debe contener los asien tos y anotaciones registrales relativos a los certificados inscritos \n conforme a los artículos 61 y 62 de esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":62},{"id":"1e053118-34f7-4f80-b11d-f29395d52a87","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 64. -","contenido":"El registro se debe llevar mediante la asignación de folios electrónicos por solicitante en los que \n deben constar los asientos relativos a la inscripción, suspensión, cancelación y demás actos de carácter registral, \n relativos a la persona solicitante y al producto, equipo o edificación o ambos objeto de la certificación.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":63},{"id":"da8a8b69-280d-46ae-8521-550a9dcc4a31","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 65. -","contenido":"La Comisión Nacional de Energía puede efectuar rectificaciones a los registros y anotaciones por \n causas de error, ya sea de oficio o a petición de parte interesada. \n Los errores materiales deben corregirse con un nuevo asiento registral sin eliminar del Registro el asiento que \n contenga el error. \n Artícu lo 66. - La Comisión Nacional de Energía debe emitir o actualizar las disposiciones relacionadas con la \n operación del registro de certificados. \n Capítulo VII \n Del Desarrollo Industrial","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De los Certificados de Energías Limpias","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":64},{"id":"42bb67d5-9980-4d44-89bd-b0f3e8a64b49","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 67. -","contenido":"La Secretaría de Economía, en coordinación con la Secretaría , debe promover el desarrollo de \n cadenas de valor de las Energías Limpias, en condiciones de sustentabilidad económica y atendiendo a las \n condiciones presupuestales aprobadas. En dicho contexto, se debe identificar los minerales críticos necesarios para \n la Transición Energética, garantizando su disponibilidad, acceso y aprovechamiento sustentable, con el fin de \n fortalecer las capacidades nacionales en la producción y adopción de Tecnologías Limpias, en congruencia con los \n objetivos de la política energética y ambiental del país.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Desarrollo Industrial","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":65},{"id":"0c4ec2d1-951b-438b-b988-b958cde9f775","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 68. -","contenido":"La Secretaría, con la colaboración de la Secretaría de Economía y con el apoyo técnico de la \n Comisión Federal de Electricidad y el Centro Nacional de Control de Energía, debe elaborar un estudio para \n determinar las nece sidades y el potencial del Sector Eléctrico en materia de Energías Limpias cada vez que se \n elabore o actualice una nueva Estrategia o un PLATEASE, de acuerdo con lo establecido en el Reglamento. \n Capítulo VIII \n Del Financiamiento para el Aprovechamiento Sust entable de la Energía","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Desarrollo Industrial","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":66},{"id":"870fcc36-d297-476e-a7a0-385955f6110c","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 69. -","contenido":"El financiamiento para el Aprovechamiento Sustentable de la Energía se debe realizar observando \n el interés público y la planeación sectorial, y tienen por objeto alguno de los siguientes fines: \n I. Contribuir a la sustitu ción de equipos y aparatos energéticamente ineficientes; \n II. Realizar las mejoras a edificaciones en las que se realice el consumo energético para su \n acondicionamiento térmico, con el fin de que este sea más eficiente, y \n III. La instalación de equipos econ ómicamente viables en las viviendas que permitan aprovechar las \n fuentes de energía renovables para la satisfacción de sus necesidades.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":67},{"id":"6bfe1bdc-bcd4-4fc6-a93b-7b7d7752db50","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 70. -","contenido":"El financiamiento para el Aprovechamiento Sustentable de la Energía se establece mediante un \n convenio entre una persona usuaria final y un financiador en el que: \n I. El financiador proporciona el capital necesario para realizar uno de los proyectos a que se refiere el \n artículo anterior, y \n II. La persona usuaria final puede autorizar al financiador a recuperar su capital y costos de \n financiamiento, a través de la facturación del Suministro Eléctrico o Distribución de gas natural de \n la persona usuaria final. \n Los financiadores pueden ser empresas comerciales o entidades financieras. \n Los programas o proyectos que est ablezcan el uso de este mecanismo de financiamiento deben ser sometidos a \n visto bueno de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":68},{"id":"2a011634-318f-4610-92a5-165d4f9756a5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 71. -","contenido":"El financiador debe procurar tasas de interés competitivas, de acuerdo con los criterios técnicos que \n para tal efecto emita la Secretaría. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 19 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":69},{"id":"3f73a2f0-0c25-4c6c-8fc4-45f1abc1036e","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 72. -","contenido":"En caso de que la Secretaría determine su conveniencia, los financiamientos referidos en este \n Capítulo deben ser pagados a través de la factura que la suministradora de electricidad o distribuidora de gas natural \n haga a cada persona usuaria por la prestación de sus servicios.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":70},{"id":"ecaaa7e2-97c1-4d6d-bd03-2ed49ad9e17c","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 73. -","contenido":"Previo al otorgamiento de los financiamientos referidos en este Capítulo, la suministradora de \n electricidad o distribuidora de gas natural debe firmar un convenio, cuyo formato debe ser aprobado por la Comi sión \n Nacional de Energía con cualquier financiador que lo solicite. \n En dichos convenios se establecen los términos para que la suministradora de electricidad o distribuidora de gas \n natural preste al financiador el servicio de cobranza a la persona usuaria final. \n En el caso de los usuarios domésticos, los convenios tipo deben ser autorizados por la Procuraduría Federal del \n Consumidor. \n La CONUEE debe determinar aquellas tecnologías económicamente viables y energéticamente eficientes \n susceptibles de financiami ento.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":71},{"id":"7c45db27-8172-46c4-a195-e7ebd7eaa7c2","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 74. -","contenido":"La Comisión Nacional de Energía debe establecer, con la aprobación de la Secretaría, el monto de \n la contraprestación a la que las suministradoras eléctricas o las distribuidoras de gas tienen derecho por la prestación \n del servicio de co branza descrito en el artículo anterior. La Comisión Nacional de Energía debe considerar el valor \n comercial de los servicios de facturación, excepto cuando el objeto del programa contribuya al combate a la Justicia \n Energética en programas públicos, en cuyo caso la contraprestación sólo corresponde al costo administrativo.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":72},{"id":"8b0bb912-f68a-43fb-809a-3735296d587b","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 75. -","contenido":"Los convenios a que se refiere el artículo 70 de la presente Ley deben estipular que, en caso de \n mora por parte de la persona usuaria, la suministradora de electricidad o dis tribuidora de gas natural no es \n responsable de los montos por cobrar.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":73},{"id":"6e003340-266f-49eb-a4ec-4a4027aa18f9","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 76. -","contenido":"La normatividad debe prever lo necesario para que el cambio de Suministradora o Distribuidora de \n una persona usuaria no afecte el cumplimiento o la ejecución de los conveni os. \n Capítulo IX \n De la Participación Voluntaria \n Sección I \n Del Reconocimiento en excelencia en Eficiencia Energética","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Financiamiento para el Aprovechamiento Sust entable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":74},{"id":"46222ba3-e492-4fe7-aa56-6ac82c224f7e","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 77. -","contenido":"El reconocimiento a la excelencia en Eficiencia Energética consta de la participación voluntaria para \n reconocer a las instalaci ones, edificaciones, empresas o productos que destaquen en el uso sustentable y eficiente \n de la energía.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"Del Reconocimiento en excelencia en Eficiencia Energética","orden":75},{"id":"c8e25db8-fc6e-4e44-b323-410c18aaa60f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 78. -","contenido":"El reconocimiento de excelencia en Eficiencia Energética está a cargo de la Secretaría, con el \n apoyo técnico de la CONUEE. Para su evalua ción y otorgamiento, la CONUEE puede solicitar el apoyo de la \n Secretaría de Medio Ambiente y Recursos Naturales, de la Secretaría de Economía y de la Secretaría de Desarrollo \n Agrario, Territorial y Urbano.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"Del Reconocimiento en excelencia en Eficiencia Energética","orden":76},{"id":"47a73729-3cae-4d0f-aa17-84e26721abdc","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 79. -","contenido":"Las personas interesadas en recibir el reconocimiento de excelencia en Eficiencia Energética deben \n cumplir los requisitos que, para tal efecto, se establezcan en las disposiciones reglamentarias aplicables que \n establezca la CONUEE, previa aprobación de la Secretaría.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"Del Reconocimiento en excelencia en Eficiencia Energética","orden":77},{"id":"9232e580-c134-4a5d-8cc2-1a9afd38b2ba","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 80. -","contenido":"La CONUEE debe integrar, administrar y actualizar el registro de instalaciones, edificaciones, \n empresas o productos que reciban el reconocimiento de excelencia en Eficiencia Energética. \n Sección II \n De los acuerdos voluntarios","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"Del Reconocimiento en excelencia en Eficiencia Energética","orden":78},{"id":"d258d3fb-0850-42de-8932-90e082efefc4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   81. -","contenido":"La Secretaría, a través de la CONUEE, puede celebrar acuerdos voluntarios con personas \n participantes de los sectores productivos que tengan consumos significativos de energía por cada unidad de \n producción física, a fin de reducir la intensidad energética en sus actividades.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":79},{"id":"22d4ac40-1706-48b4-8cf2-2a1d2d3f6660","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo   82. -","contenido":"Los acuerdos voluntarios deben especificar la meta de reducción en la intensidad energética que se \n comprometen a implementar las personas participantes durante la vigencia del acuerdo. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 20 de 23 \n Esta meta debe ser establecida y actualizada cada tres años y deb e ser tomada como referencia mínima en los \n acuerdos voluntarios subsecuentes que se celebren.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":80},{"id":"8ca37e41-6708-4f60-bc25-0a9b5c45bf88","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 83. -","contenido":"Los requisitos y procedimientos para la celebración de los acuerdos voluntarios a que hace \n referencia el artículo anterior, los mecanismos y procedi mientos para realizar la verificación de su cumplimiento, se \n deben determinar en el Reglamento de esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":81},{"id":"a3ee9ba8-5f9a-46f9-ae74-18ce774e7955","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 84. -","contenido":"La Secretaría, en colaboración con otras entidades de la administración pública, deben desarrollar, \n coordinar e implementar diversos m ecanismos de reconocimiento y comunicación de los logros obtenidos por las \n personas participantes de los acuerdos voluntarios. \n La CONUEE debe proponer a la Secretaría mecanismos de reconocimiento y comunicación de los logros \n obtenidos por las personas part icipantes de los acuerdos voluntarios.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":82},{"id":"6e46811a-3dd8-479b-a617-d95e22bf96d0","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 85. -","contenido":"Cada dos años, la CONUEE debe elaborar y difundir, a más tardar el 31 de julio, un reporte de \n evaluación sobre los acuerdos voluntarios. Este reporte debe estimar los ahorros generados por las medidas de \n reducción en la intensidad energética derivadas de los acuerdos celebrados. \n Para la estimación de los ahorros a que se refiere el párrafo anterior, la CONUEE puede apoyarse en expertos \n independientes. \n Con base en este reporte, la Secretaría debe determina r la conveniencia de establecer cumplimientos obligatorios \n de acciones de Eficiencia Energética para determinados sectores productivos. En su caso, la Secretaría puede emitir \n las disposiciones administrativas que regulen las obligaciones, medios de verific ación y sanciones correspondientes, \n así como las determinaciones necesarias para su operación.","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":83},{"id":"59ee5491-cdd2-4d22-9ac7-232143859735","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 86. -","contenido":"La Secretaría, en colaboración con la Secretaría de Economía y el apoyo técnico de la CONUEE, \n debe diseñar y establecer un programa para asesorar y apoyar a las micros, pequeñas y medianas empresas en la \n implementación de medidas de Eficiencia Energética, informar sobre los beneficios que ésta conlleva, e identificar las \n opciones de financiamiento para que éstas realicen mejoras de Eficiencia Energét ica. \n TÍTULO CUARTO \n De la Transparencia y Acceso a la Información","tipo_articulo":"ordinario","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":84},{"id":"ca61baeb-f6cf-4a40-acbf-244c4ed2db80","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 87. -","contenido":"La Secretaría, con apoyo del Instituto Nacional de Electricidad y Energías Limpias, debe elaborar y \n desarrollar una página de Internet que incluya los reportes y documentos requ eridos en la presente Ley.","tipo_articulo":"ordinario","titulo_nombre":"De la Transparencia y Acceso a la Información","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":85},{"id":"d3193ac1-be81-4ed9-9d2e-d1c66fa4df92","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 88. -","contenido":"Los recursos federales que se transfieran a las Entidades Federativas, municipios y particulares, a \n través de los convenios de coordinación o de proyectos aprobados por los fondos, se sujetan a las disposiciones \n fed erales en materia de transparencia y evaluación de los recursos públicos. \n TÍTULO QUINTO \n De la Inspección, Vigilancia y Sanciones \n Capítulo I \n De la Inspección y Vigilancia","tipo_articulo":"ordinario","titulo_nombre":"De la Transparencia y Acceso a la Información","capitulo_nombre":"De la Participación Voluntaria","seccion_nombre":"De los acuerdos voluntarios","orden":86},{"id":"5b5f5302-c29b-4d93-843d-661dfc1f0a30","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 89. -","contenido":"La Secretaría de Energía y la Comisión Nacional de Energía pueden realiz ar visitas de verificación, \n inspección y vigilancia, de acuerdo con las disposiciones aplicables.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":87},{"id":"aaf42b4a-937d-4977-a89b-33cc2840f0eb","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 90. -","contenido":"La CONUEE puede, de manera aleatoria o cuando lo considere necesario, vigilar y supervisar de \n forma física o remota la ejecución de los procesos que desarrollen los particulares para mejorar su Eficiencia \n Energética y ordenar visitas de verificación a los Usuarios de Patrón de Alto Consumo de energía, a las Empresas \n Públicas del Estado y a la Administración Pública Federal. \n Capítulo II \n De las Sanc iones \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 21 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":88},{"id":"8ecc4f47-ce7e-4726-bdee-0d33753af789","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 91. -","contenido":"La Secretaría, la Comisión Nacional de Energía o la CONUEE pueden sancionar con multas de cien \n a mil veces el valor de la Unidad de Medida y Actualización vigente, u otras medidas, a los sujetos obligados que no \n le proporcionen la infor mación a que se refiere esta Ley o que proporcionen información falsa o incompleta, sin \n perjuicio de las responsabilidades civiles, penales o fiscales en que dichas personas usuarias incurran en adición a \n estas. \n Para el procedimiento por infracciones a la presente Ley, se debe aplicar supletoriamente la Ley Federal de \n Procedimiento Administrativo.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":89},{"id":"8900af54-ebe0-4265-b9ea-a57679c135d4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 92. -","contenido":"La Procuraduría Federal del Consumidor puede sancionar con multas las conductas u omisiones \n siguientes: \n I. De cien a diez mil veces el valor de la U nidad de Medida y Actualización vigente a la persona que \n fabrique, importe, distribuya o comercialice los equipos o aparatos a que hace referencia el \n presente ordenamiento, que no incluyan la información acerca del consumo energético, o cuando \n la incluyan de forma diferente a la que establezcan las Normas Oficiales Mexicanas, el Reglamento \n o disposiciones emanados de esta Ley, siempre que no implique engaño al consumidor o no \n constituya una práctica que pueda inducir a error; \n II. De tres mil a catorce mil v eces el valor de la Unidad de Medida y Actualización vigente a la persona \n que incluya en los aparatos o equipos a que hace referencia la presente Ley, información falsa o \n incompleta que implique engaño al consumidor o constituya una práctica que pueda indu cir a error, \n y \n III. De cinco mil a veinte mil veces el valor de la Unidad de Medida y Actualización vigente a la \n persona física o moral que importe, distribuya o comercialice equipos o aparatos a que hace \n referencia el presente artículo, que incluyan infor mación falsa o incompleta que implique engaño al \n consumidor o constituya una práctica que pueda inducir a error. \n Para la sustanciación del procedimiento por infracciones a la Ley a que se refiere el presente precepto, se aplica \n lo dispuesto en la Ley Feder al de Protección al Consumidor. Estas sanciones se imponen sin perjuicio de las que \n procedan civil, administrativa, penal o fiscalmente.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":90},{"id":"0739db00-1daf-4b29-ae55-387ab49bb95f","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 93. -","contenido":"La Comisión Nacional de Energía puede sancionar con multa de veinticinco a setenta y cinco mil \n veces el v alor de la Unidad de Medida y Actualización vigente, a la suministradora de electricidad o distribuidora de \n gas natural que niegue el servicio de cobranza derivado de los convenios establecidos a los que se refiere el artículo \n 70 de esta Ley.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":91},{"id":"35a5b9bf-a381-461d-b82d-538cbf0966a1","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 94. -","contenido":"En caso de reincidencia se duplica la multa que previamente se haya impuesto. \n Se entiende por reincidencia, para los efectos de esta Ley y demás disposiciones derivadas de ella, cada una de \n las subsecuentes infracciones a un mismo precepto, cometidas dent ro de los dos años siguientes a la fecha en que \n se impuso la infracción precedente, siempre que esta no hubiese sido declarada inválida por autoridad competente.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":92},{"id":"ab094bad-5781-457c-b123-d07a039f42b5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 95. -","contenido":"En la imposición de multas, se debe considerar la gravedad de la infracción, el daño causado, los \n indicios de intencionalidad, la duración de la conducta y la reincidencia o antecedentes del infractor, así como su \n capacidad económica.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":93},{"id":"d0af04ce-bebc-401f-8374-81f8d2ba8f7e","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 96. -","contenido":"Los ingresos percibidos por la imposición de las sanciones establecidas en la presente Ley se \n deben aportar a los fondos que se constituyan para la Transición Energética y el Aprovechamiento Sustentable de la \n Energía. \n Capítulo III \n De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Inspección y Vigilancia","seccion_nombre":"De los acuerdos voluntarios","orden":94},{"id":"71a8ba7e-3c48-4fcc-bb55-bac1911caee4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 97. -","contenido":"Las personas servidoras públicas encargadas de la aplicación y vigilancia del cumplimiento de esta \n Ley, pueden ser acreedoras a las sanciones administrativas aplicables en caso de incumplimiento de sus \n disposiciones de acuerdo con lo dispuesto en la Ley General de Resp onsabilidades Administrativas y demás \n legislación que resulte aplicable, sin perjuicio de la responsabilidad civil y penal a que haya lugar.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":95},{"id":"c4fee54e-249e-439d-91b1-4f8e1e66aa7d","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 98. -","contenido":"El incumplimiento a la presente Ley puede ser sancionado por la Secretaría y la CONUEE en el \n ámbito d e sus atribuciones. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 22 de 23","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":96},{"id":"ec247328-bc97-4782-9de4-f601f49c79b8","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 99. -","contenido":"Los Usuarios de Patrón de Alto Consumo de energía, que cometan las faltas señaladas en la Ley, \n deben ser sancionados por la CONUEE con apoyo de la Secretaría, conforme a lo establecido en el presente \n ordenamiento legal. \n Pa ra efectos de lo señalado en el párrafo anterior, la CONUEE con apoyo de la Secretaría, debe observar lo \n dispuesto por esta Ley, según corresponda, así como lo previsto por la Ley Federal de Procedimiento Administrativo.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":97},{"id":"94b6f536-f431-4d53-9b1f-bff51617fd12","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Artículo 100. -","contenido":"Las sanciones a pers onas fabricantes, importadoras, distribuidoras y comercializadoras que \n cometan faltas administrativas con relación a la información sobre el consumo energético de equipos y aparatos, \n deben ser aplicadas de conformidad con la presente Ley, la Ley Federal de Protección al Consumidor y las demás \n disposiciones aplicables.","tipo_articulo":"ordinario","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":98},{"id":"4368a543-99b0-4734-afac-1351a861d4a4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio PRIMERO.","contenido":"- La presente Ley entrará en vigor al día siguiente de su publicación en el Diario Oficial de la Federación.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":99},{"id":"bee3266a-817e-434b-a9e9-79aaa8d2b4c1","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio SEGUNDO.","contenido":"- Se abroga la Ley de Transición Energética publicada en el Diario Oficial de la Federación el 24 de \n diciembre de 2015, y las demás disposiciones que se opongan al presente ordenamiento.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":100},{"id":"08209c44-1f03-4552-99a2-bb8fb31c5dfc","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio TERCERO.","contenido":"- En tanto se emita la nueva regulación o se modifique la regulación correspondiente, la normatividad y \n regulación emitidas por la Secretaría con anterioridad a la entrada en vigor de la presente Ley, continúan en vigor, sin \n perjuicio de que puedan ser adecuadas, modificadas o sustituidas, en términos de las disposiciones de esta Ley y las \n demás disposiciones aplicable s. \n Las referencias legales o reglamentarias a la Ley de Transición Energética se entienden hechas en lo aplicable, a \n la Ley de Planeación y Transición Energética.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":101},{"id":"06bee850-6569-432a-b9e5-8bd24e7952b0","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio CUARTO.","contenido":"- El Ejecutivo Federal debe expedir el Reglamento de esta Ley dentro de los ciento och enta días naturales \n siguientes a la fecha de su entrada en vigor.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":102},{"id":"39253d0b-3d3f-48d1-b821-62dd9a32f9c5","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio QUINTO.","contenido":"- En tanto se expiden el Reglamento correspondiente la Secretaría tiene la facultad para ejercer las \n atribuciones que le otorga la presente Ley a partir de su entrada en vigor.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":103},{"id":"ba94aa33-94c1-42a6-8c60-ba04d44ba3d4","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio SEXTO.","contenido":"- La Secretaría de Energía dentro de un plazo no mayor a trescientos sesenta y cinco días naturales \n contados a partir de la entrada en vigor de la presente Ley debe publicar en el Diario Oficial de la Federación, la \n Estrategia Nacional de Transición Energé tica, el Plan para la Transición Energética y el Aprovechamiento \n Sustentable de la Energía, el Plan de Desarrollo del Sector Eléctrico y el Plan de Desarrollo del Sector Hidrocarburos. \n La Secretaría de Energía fijará como meta una participación mínima de e nergías limpias en la generación de \n energía eléctrica, la cual debe corresponder a las metas de largo plazo establecidas en la Ley General de Cambio \n Climático.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":104},{"id":"b7126310-3610-4058-8a7c-b45f9e03ce07","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio SÉPTIMO.","contenido":"- A partir de la entrada en vigor de la presente Ley, el Fondo de Servicio Universal Elé ctrico cambia de \n denominación a Fondo de Servicio Universal Energético, por lo cual debe continuar operando conforme a sus \n contratos de fideicomiso actual en tanto se actualice la normatividad aplicable y en demás disposiciones que no se \n opongan a la prese nte Ley.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":105},{"id":"bd562f9e-3cda-4b69-8323-59142e598a60","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio OCTAVO.","contenido":"- El Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía debe seguir \n operando conforme a sus contratos de fideicomiso actual en tanto se actualice la normatividad aplicable. De igual \n manera el Acuerdo por el q ue se dan a conocer las disposiciones generales aplicables a la administración y \n operación de los apoyos para las actividades de investigación científica, desarrollo tecnológico e innovación en \n materia de hidrocarburos y de sustentabilidad energética, publ icado en el Diario Oficial de la Federación el 19 de \n agosto de 2021 y los lineamientos que se derivan de este acuerdo siguen vigentes, sin perjuicio de que puedan ser \n adecuadas, modificadas o sustituidas, en términos de las disposiciones de esta Ley y las demás disposiciones \n aplicables.","tipo_articulo":"transitorio","titulo_nombre":"De la Transición En ergética y la reducción de la Pobreza Energética","capitulo_nombre":"Del Fondo para la Transición Energética y el Aprovechamiento S ustentable de la Energía","seccion_nombre":"De la información en materia de Eficiencia Energética","orden":106},{"id":"b24e7517-7c92-4829-8a99-a8ac81479459","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio ARTÍCULO SEXTO","contenido":"A ARTÍCULO DÉCIMO. - … … ..","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":107},{"id":"ee74a6d9-fcb8-46ad-8c65-992c6c257f0a","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio PRIMERO.","contenido":"El presente Decreto entrará en vigor el día siguiente al de su publicación en el Diario Oficial de la \n Federación.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":108},{"id":"495e8f06-9b38-4c7d-a1e1-c9a9de0bbcd3","ley_id":"d19354e7-fbf9-427b-aa91-55017b027e0a","identificador":"Transitorio SEGUNDO.","contenido":"La Cámara de Diputados debe r ealizar las previsiones presupuestales necesarias para que las \n dependencias y entidades puedan cumplir las atribuciones conferidas en este Decreto. \n\nLEY DE PLANEACIÓN Y TRANSICIÓN ENERGÉTICA \n C ÁMARA DE D IPUTADOS DEL H. C ONGRESO DE LA U NIÓN \n Se cretaría General \n Secretaría de Servicios Parlamentarios \n Nueva Ley DOF 18 - 03 - 2025 \n 23 de 23 \n Ciudad de México, a 12 de marzo de 2025 . - Sen. Gerardo Fernández Noroña, Presidente. - Dip. Sergio Carlos \n Gut iérrez Luna, Presidente. - Sen. Verónica Noemí Camino Farjat, Secretaria . - Dip. José Luis Montalvo Luna, \n Secretario. - Rúbricas. \" \n En cumplimiento de lo dispuesto por la fracción I del Artículo 89 de la Constitución Política de los Estados Unidos \n Mexicanos, y para su debida publicación y observancia, expido el presente Decreto en la Residencia del Poder \n Ejecutivo Federal, en la Ciudad de México, a 18 de marzo de 2025. - Claudia Sheinbaum Pardo , Presidenta de los \n Estados Unidos Mexicanos. - Rúbrica. - Lcda. Rosa I cela Rodríguez Velázquez , Secretaria de Gobernación. - \n Rúbrica.","tipo_articulo":"transitorio","titulo_nombre":"De la Inspección, Vigilancia y Sanciones","capitulo_nombre":"De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","seccion_nombre":"De los acuerdos voluntarios","orden":109}],"remove":["ba019c84-c4f2-5bd9-9118-3f3a8bce7fbc","66f94ecf-ae55-500b-a37b-a456295d9dc5","9c43a394-d870-5c83-bbf1-433074686e02"],"themes_before":[{"nivel":"titulo","nombre":"TÍTULO PRIMERO Disposiciones Generales","orden":0},{"nivel":"capitulo","nombre":"Capítulo Único Del Objeto de la Ley y Definiciones","orden":1},{"nivel":"titulo","nombre":"TÍTULO SEGUNDO De la Planeación del Sector Energético","orden":2},{"nivel":"capitulo","nombre":"Capítulo I De las Autoridades y Organismos","orden":3},{"nivel":"capitulo","nombre":"Capítulo II Del Consejo de Planeación Energética","orden":4},{"nivel":"capitulo","nombre":"Capítulo III De los Instrumentos de Planeación Energética","orden":5},{"nivel":"capitulo","nombre":"Capítulo IV De la Información Energética","orden":6},{"nivel":"seccion","nombre":"Sección I Del Sistema Nacional de Información Energética","orden":7},{"nivel":"seccion","nombre":"Sección II De la información en materia de Eficiencia Energética","orden":8},{"nivel":"titulo","nombre":"TÍTULO TERCERO De la Transición Energética y la reducción de la Pobreza Energética","orden":9},{"nivel":"capitulo","nombre":"Capítulo I Del Financiamiento","orden":10},{"nivel":"capitulo","nombre":"Capítulo II Del Fondo para la Transición Energética y el Aprovechamiento Sustentable de la Energía","orden":11},{"nivel":"capitulo","nombre":"Capítulo III Del Fondo de Servicio Universal Energético","orden":12},{"nivel":"capitulo","nombre":"Capítulo IV De los Recursos de Innovación, Desarrollo Tecnológico y Formación de Recursos Humanos","orden":13},{"nivel":"capitulo","nombre":"Capítulo V De la Investigación Científica, la Innovación y el Desarrollo Tecnológico","orden":14},{"nivel":"capitulo","nombre":"Capítulo VI De los Certificados de Energías Limpias","orden":15},{"nivel":"capitulo","nombre":"Capítulo VII Del Desarrollo Industrial","orden":16},{"nivel":"capitulo","nombre":"Capítulo VIII Del Financiamiento para el Aprovechamiento Sustentable de la Energía","orden":17},{"nivel":"capitulo","nombre":"Capítulo IX De la Participación Voluntaria","orden":18},{"nivel":"seccion","nombre":"Sección I Del Reconocimiento en excelencia en Eficiencia Energética","orden":19},{"nivel":"seccion","nombre":"Sección II De los acuerdos voluntarios","orden":20},{"nivel":"titulo","nombre":"TÍTULO CUARTO De la Transparencia y Acceso a la Información","orden":21},{"nivel":"titulo","nombre":"TÍTULO QUINTO De la Inspección, Vigilancia y Sanciones","orden":22},{"nivel":"capitulo","nombre":"Capítulo I De la Inspección y Vigilancia","orden":23},{"nivel":"capitulo","nombre":"Capítulo II De las Sanciones","orden":24},{"nivel":"capitulo","nombre":"Capítulo III De la Responsabilidad de las personas servidoras públicas, personas usuarias u otras","orden":25}],"themes_after":[],"date_before":"2025-03-18","date_after":"2025-03-18"}$payload$::jsonb; lid uuid; n integer;
BEGIN
 lid := (p->>'ley_id')::uuid;
 LOCK TABLE public.articulos, public.temas, public.user_favorites, public.user_notes IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.leyes WHERE id=lid FOR UPDATE;
 IF NOT EXISTS(SELECT 1 FROM public.leyes WHERE id=lid AND fecha_publicacion=(p->>'date_before')::date) THEN RAISE EXCEPTION 'Cambió la fecha o el instrumento'; END IF;
 SELECT count(*) INTO n FROM public.articulos WHERE ley_id=lid;
 IF n<>jsonb_array_length(p->'before') THEN RAISE EXCEPTION 'Cambió el conteo antes de aplicar'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p->'before') b LEFT JOIN public.articulos a ON a.id=(b->>'id')::uuid WHERE a.id IS NULL OR md5(a.contenido) IS DISTINCT FROM b->>'contenido_md5' OR (to_jsonb(a)-'contenido'-'fts'-'created_at') IS DISTINCT FROM (b-'contenido_md5')) THEN RAISE EXCEPTION 'El respaldo ya no coincide con los artículos'; END IF;
 IF (SELECT count(*) FROM public.temas WHERE ley_id=lid)<>jsonb_array_length(p->'themes_before') OR EXISTS(SELECT 1 FROM jsonb_array_elements(p->'themes_before') b WHERE NOT EXISTS(SELECT 1 FROM public.temas t WHERE t.ley_id=lid AND (to_jsonb(t)-'created_at'-'id'-'ley_id')=b)) THEN RAISE EXCEPTION 'Cambió el índice de temas'; END IF;
 IF EXISTS(SELECT 1 FROM public.user_favorites f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) OR EXISTS(SELECT 1 FROM public.user_notes f WHERE f.articulo_id IN(SELECT jsonb_array_elements_text(p->'remove'))) THEN RAISE EXCEPTION 'Hay referencias nuevas a fragmentos que se unirán: revisar traslado'; END IF;
 INSERT INTO public.articulos(id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden)
 SELECT id,ley_id,identificador,contenido,tipo_articulo,titulo_nombre,capitulo_nombre,seccion_nombre,orden FROM jsonb_populate_recordset(null::public.articulos,p->'after')
 ON CONFLICT(id) DO UPDATE SET identificador=excluded.identificador,contenido=excluded.contenido,tipo_articulo=excluded.tipo_articulo,titulo_nombre=excluded.titulo_nombre,capitulo_nombre=excluded.capitulo_nombre,seccion_nombre=excluded.seccion_nombre,orden=excluded.orden;
 DELETE FROM public.articulos WHERE ley_id=lid AND id IN(SELECT jsonb_array_elements_text(p->'remove')::uuid);
 DELETE FROM public.temas WHERE ley_id=lid;
 insert into public.temas(id,ley_id,nivel,nombre,orden) overriding system value select (t->>'id')::bigint,lid,t->>'nivel',t->>'nombre',(t->>'orden')::int from jsonb_array_elements(p->'themes_after') t;
 UPDATE public.leyes SET fecha_publicacion=(p->>'date_after')::date WHERE id=lid;
